import 'package:flutter/material.dart';import 'package:go_router/go_router.dart';import '../../core/routes/app_routes.dart';import '../../core/utils/formatters.dart';import '../../services/tax_assessment_service.dart';import '../../widgets/error_state.dart';import '../../widgets/money_tile.dart';
class AssessmentDetailScreen extends StatefulWidget {final TaxAssessmentService service;final int id;const AssessmentDetailScreen({super.key,required this.service,required this.id});@override State<AssessmentDetailScreen> createState()=>_AssessmentDetailScreenState();}
class _AssessmentDetailScreenState extends State<AssessmentDetailScreen>{late Future<Map<String,dynamic>> future;@override void initState(){super.initState();reload();}void reload(){setState(()=>future=widget.service.find(widget.id));}Future<void> remove()async{try{await widget.service.delete(widget.id);if(mounted)context.go(AppRoutes.assessments);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Impostos apurados'),actions:[IconButton(icon:const Icon(Icons.delete_outline),onPressed:remove)]),body:FutureBuilder<Map<String,dynamic>>(future:future,builder:(ctx,s){if(!s.hasData){if(s.hasError)return ErrorState(message:'${s.error}',onRetry:reload);return const Center(child:CircularProgressIndicator());}final a=s.data!;return ListView(padding:const EdgeInsets.all(16),children:[Text('${a['name']}',style:Theme.of(context).textTheme.headlineSmall),MoneyTile(label:'ICMS destacado nas entradas',value:double.parse('${a['total_icms']}')),MoneyTile(label:'IPI destacado nas entradas',value:double.parse('${a['total_ipi']}')),const Padding(padding:EdgeInsets.all(12),child:Text('A apuração fiscal definitiva exige créditos, débitos de saídas, ajustes e enquadramento tributário.')),Text('Notas selecionadas (${a['invoice_count']}):',style:Theme.of(context).textTheme.titleMedium),...(a['invoices'] as List).map((item)=>ListTile(title:Text('NF ${item['number']} — ${item['supplier']}'),subtitle:Text('${item['issue_date']}'),trailing:Text(Formatters.money(double.parse('${item['gross_total']}')))))]); }));}
}
